create or replace function private.utf16_length(input text) returns integer language sql immutable set search_path='' as $$ select coalesce(sum(case when octet_length(convert_to(substring(input from n for 1),'UTF8'))=4 then 2 else 1 end),0)::integer from generate_series(1,char_length(input)) n $$;
create or replace function private.valid_text_run_input(input jsonb) returns boolean language sql immutable set search_path='' as $$ select extensions.jsonb_matches_schema($contract${"$schema":"http://json-schema.org/draft-07/schema#","type":"object","properties":{"version":{"type":"number","const":2},"message":{"type":"string","maxLength":4000,"pattern":"\\S"},"history":{"maxItems":12,"type":"array","items":{"type":"object","properties":{"role":{"type":"string","enum":["user","assistant"]},"text":{"type":"string","maxLength":4000,"pattern":"\\S"}},"required":["role","text"],"additionalProperties":false}}},"required":["version","message","history"],"additionalProperties":false}$contract$::json,input) and private.utf16_length(input->>'message')<=4000 and not exists(select 1 from jsonb_array_elements(input->'history') item where private.utf16_length(item->>'text')>4000) $$;
create or replace function private.valid_stored_run_input(input jsonb) returns boolean language sql immutable set search_path='' as $$ select case when extensions.jsonb_matches_schema($contract${"$schema":"http://json-schema.org/draft-07/schema#","anyOf":[{"type":"object","properties":{"template":{"type":"string","enum":["product_delivery","cs_operations"]},"version":{"type":"number","const":1},"objective":{"type":"string","maxLength":4000,"pattern":"\\S"},"context":{"type":"string","maxLength":4000,"pattern":"\\S"},"hardConstraints":{"maxItems":8,"type":"array","items":{"type":"object","properties":{"kind":{"type":"string","enum":["requirement","prohibition"]},"text":{"type":"string","maxLength":4000,"pattern":"\\S"}},"required":["kind","text"],"additionalProperties":false}},"conceptIds":{"maxItems":12,"type":"array","items":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"}},"unknowns":{"type":"string","maxLength":4000}},"required":["template","version","objective","context","hardConstraints","conceptIds","unknowns"],"additionalProperties":false},{"type":"object","properties":{"version":{"type":"number","const":2},"message":{"type":"string","maxLength":4000,"pattern":"\\S"},"history":{"maxItems":12,"type":"array","items":{"type":"object","properties":{"role":{"type":"string","enum":["user","assistant"]},"text":{"type":"string","maxLength":4000,"pattern":"\\S"}},"required":["role","text"],"additionalProperties":false}}},"required":["version","message","history"],"additionalProperties":false}]}$contract$::json,input) is not true then false when input->>'version'='2' then private.valid_text_run_input(input) else private.utf16_length(input->>'objective')<=4000 and private.utf16_length(input->>'context')<=4000 and private.utf16_length(input->>'unknowns')<=4000 and not exists(select 1 from jsonb_array_elements(input->'hardConstraints') item where private.utf16_length(item->>'text')>4000) end $$;
revoke all on function private.utf16_length(text),private.valid_stored_run_input(jsonb),private.valid_text_run_input(jsonb) from public,anon,authenticated;
